changes.evals/skills/migration-review/cases/task:
{
  "kind": "task",
  "prompt": "Review the migration this pull request adds, migrations/0042_region.sql.",
  "expectations": [
    {
      "text": "A finding names the unbatched backfill",
      "source": {
        "contract": {
          "path": "migrations/0042_region.sql",
          "line": 2,
          "quote": "UPDATE orders SET region = 'us' WHERE country = 'US';"
        }
      },
      "judged": {
        "question": "Is there a finding on the UPDATE of migrations/0042_region.sql that says it runs as one unbatched statement on a large table?",
        "pass": "Yes when a finding names the UPDATE and says it is not batched.",
        "fail": "No when no finding names the UPDATE.",
        "examples": {
          "pass": [
            "Line 2 updates every US order in one statement; batch it."
          ],
          "fail": [
            "Looks fine."
          ]
        }
      }
    },
    {
      "text": "Each finding gives its file and line",
      "source": "format",
      "judged": {
        "question": "Does each finding give the migration file and line it is about?",
        "pass": "Yes when every finding has a file and a line.",
        "fail": "No when a finding has no line.",
        "examples": {
          "pass": [
            "migrations/0042_region.sql:2"
          ],
          "fail": [
            "The backfill is risky."
          ]
        }
      }
    }
  ]
}

{
  "kind": "task",
  "prompt": "Check migrations/0019_email_index.sql in this PR before it merges.",
  "expectations": [
    {
      "text": "A finding names the locking index build",
      "source": {
        "contract": {
          "path": "migrations/0019_email_index.sql",
          "line": 1,
          "quote": "CREATE INDEX idx_users_email ON users (email);"
        }
      },
      "judged": {
        "question": "Is there a finding that the CREATE INDEX of migrations/0019_email_index.sql locks writes to users while it builds?",
        "pass": "Yes when a finding says the index build blocks writes and names line 1.",
        "fail": "No when no finding names the lock.",
        "examples": {
          "pass": [
            "Line 1 builds the index without CONCURRENTLY, so writes to users wait."
          ],
          "fail": [
            "Add a comment to the file."
          ]
        }
      }
    }
  ]
}
